export function isCustomerLanguage(value: string | null): value is CustomerLanguage {
  return customerLanguages.some(language => language.code === value);
}

function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null;
  const prefix = `${encodeURIComponent(name)}=`;
  const entry = document.cookie.split('; ').find(value => value.startsWith(prefix));
  return entry ? decodeURIComponent(entry.slice(prefix.length)) : null;
}

export function setCustomerLanguagePreference(language: CustomerLanguage): void {
  if (typeof document === 'undefined') return;
  const secure = window.location.protocol === 'https:' ? '; Secure' : '';
  document.cookie = `wt_customer_language=${encodeURIComponent(language)}; Max-Age=${60 * 60 * 24 * 365}; Path=/; SameSite=Lax${secure}`;
}

export function detectCustomerLanguage(languages: readonly string[] = typeof navigator === 'undefined' ? ['en'] : navigator.languages): CustomerLanguage {
  const regionDefaults: Record<string, CustomerLanguage> = {
    FR: 'fr', ES: 'es', DE: 'de', PT: 'pt', IT: 'it', JP: 'ja', CN: 'zh', SG: 'zh', TW: 'zh', HK: 'zh', KR: 'ko', NL: 'nl', BE: 'nl', SA: 'ar', AE: 'ar', EG: 'ar', IN: 'hi', US: 'en', GB: 'en', AU: 'en', CA: 'en', IE: 'en', NZ: 'en',
  };
  for (const locale of languages) {
    try {
      const parsed = new Intl.Locale(locale);
      const language = customerLanguages.find(option => option.code === parsed.language);
      if (language) return language.code;
      const regional = parsed.region ? regionDefaults[parsed.region.toUpperCase()] : undefined;
      if (regional) return regional;
    } catch {
      continue;
    }
  }
  return 'en';
}

export function getCustomerLanguagePreference(): CustomerLanguage {
  const saved = getCookie('wt_customer_language');
  if (isCustomerLanguage(saved)) return saved;
  return detectCustomerLanguage();
}

export function translateCustomerPortal(language: CustomerLanguage, phrase: Phrase | SupplementalPhrase, values?: Record<string, string | number>): string {
  const template = phrase in english
    ? language === 'en' ? english[phrase as Phrase] : translations[language as Exclude<CustomerLanguage, 'en'>][phrase as Phrase]
    : supplementalTranslations[language][phrase as SupplementalPhrase];
  return template.replace(/\{(\w+)\}/g, (_match: string, key: string) => String(values?.[key] ?? `{${key}}`));
}
